        "0.05 0.07 0.10 rg",
        "30 450 552 175 re f",
        "0.00 0.80 0.95 RG 1 w",
        "30 450 552 175 re S",
        "BT",
        "/F1 10 Tf",
        "0.00 0.95 1.00 rg",
        "45 605 Td",
        "(SMT-LIB2 FIRST-ORDER THEOREM SPECIFICATION) Tj",
        "/F1 8 Tf",
        "0.75 0.80 0.90 rg",
        "0 -16 Td",
        f"(Formula: {_clean_latin1(result.formula_str[:68])}) Tj",
    ])

    if len(result.formula_str) > 68:
        stream_lines.extend([
            "0 -12 Td",
            f"(         {_clean_latin1(result.formula_str[68:136])}) Tj",
